1	// Package relayproof implements cross-chain message verification.
2	package relayproof
3	
4	import (
5		"errors"
6		"fmt"
7		"os"
8		"path/filepath"
9		"sort"
10		"strconv"
11		"sync"
12		"syscall"
13	)
14	
15	// Durable queue statuses. Pending and waiting are live; the rest are terminal.
16	const (
17		StatusPending    = "pending"        // accepted, not processed for the first time yet
18		StatusWaiting    = "waiting"        // processed, waiting for a trusted header at proof height
19		StatusSuccess    = "success"        // recorded locally and nonce consumed
20		StatusReplay     = "replay"         // nonce combination already consumed by another message
21		StatusExpired    = "expired"        // absolute expiry reached before delivery
22		StatusUnknownSrc = "unknown-source" // source chain was never registered
23	)
24	
25	// Common errors. Callers can compare with errors.Is.
26	var (
27		// ErrConflict is returned when an id is reused with different message content.
28		ErrConflict = errors.New("message id conflict: existing record has different content")
29		// ErrTerminal is returned when re-submitting a terminal id or attempting to
30		// reactivate it.
31		ErrTerminal = errors.New("message is terminal and cannot be reactivated")
32		// ErrInvalidArg is returned for malformed input (empty id, bad times, ...).
33		ErrInvalidArg = errors.New("invalid argument")
34		// ErrLocked is returned when another process holds the state directory open.
35		ErrLocked = errors.New("state directory is locked by another process")
36		// ErrCorrupt is returned when on-disk state is unreadable or unsupported.
37		ErrCorrupt = errors.New("state directory is corrupt or uses an unsupported format")
38		// ErrStorage is returned after a storage failure; the queue must be reopened.
39		ErrStorage = errors.New("storage failure; queue must be reopened")
40	)
41	
42	// Envelope is a submitted message together with its absolute expiry time.
43	type Envelope struct {
44		Message Message
45		// ExpiresAt is an absolute Unix-millisecond instant. Zero means never expire.
46		ExpiresAt int64
47	}
48	
49	// Record is the full persisted state of one submitted message.
50	type Record struct {
51		Msg        Envelope
52		Status     string
53		Reason     string
54		Seq        int64 // submission order, zero-based
55		Attempts   int   // number of processing attempts
56		NextRetry  int64 // 0 when not yet processed, or terminal
57		LastProcAt int64 // processing time of the most recent attempt
58	}
59	
60	// Query is the user-visible view of a Record.
61	type Query struct {
62		ID        string
63		From      string
64		To        string
65		Nonce     uint64
66		Payload   string
67		ProofAt   int64
68		ExpiresAt int64
69		Status    string
70		Reason    string
71		NextRetry int64 // 0 = no retry scheduled (not yet processed, or terminal)
72		Attempts  int
73	}
74	
75	// AdvanceReport is the outcome of one Advance call.
76	type AdvanceReport struct {
77		Now     int64
78		Results []Result
79	}
80	
81	// Result describes what happened to one message during an Advance.
82	type Result struct {
83		ID     string `json:"id"`
84		Status string `json:"status"`
85		Reason string `json:"reason"`
86	}
87	
88	// Queue is a durable local outbox backed by a state directory. A single
89	// Queue owns the directory for writes; other processes attempting to Open the
90	// same directory fail with ErrLocked. It is safe for concurrent use by
91	// multiple goroutines, and a success record plus its nonce consumption commit
92	// as one durable unit.
93	type Queue struct {
94		mu sync.Mutex
95	
96		store  *store
97		flock  *os.File
98		broken bool // a storage write failed; all further mutations fail
99	
100		now      int64                   // last advanced Unix-ms time, 0 = never advanced
101		sources  map[string]bool         // registered source chains
102		headers  map[string]Header       // latest registered header per chain
103		records  map[string]*Record      // by message id
104		order    []string                // non-terminal messages, submission order
105		consumed map[consumeToken]string // (source, destination, nonce) -> successful message id
106		nextSeq  int64
107	}
108	
109	// Open opens (creating if needed) a persistent queue backed by stateDir. It
110	// takes an exclusive process lock on the directory and refuses to start when
111	// the on-disk state is corrupt or in an unsupported format, never clearing it.
112	func Open(stateDir string) (*Queue, error) {
113		if stateDir == "" {
114			return nil, fmt.Errorf("%w: empty state directory", ErrInvalidArg)
115		}
116		if err := os.MkdirAll(stateDir, 0o755); err != nil {
117			return nil, fmt.Errorf("create state directory: %w", err)
118		}
119		abs, err := filepath.Abs(stateDir)
120		if err != nil {
121			return nil, fmt.Errorf("resolve state directory: %w", err)
122		}
123	
124		lockPath := filepath.Join(abs, "lock")
125		lock, err := os.OpenFile(lockPath, os.O_CREATE|os.O_RDWR, 0o644)
126		if err != nil {
127			return nil, fmt.Errorf("open lock file: %w", err)
128		}
129		if err := syscall.Flock(int(lock.Fd()), syscall.LOCK_EX|syscall.LOCK_NB); err != nil {
130			lock.Close()
131			return nil, fmt.Errorf("%w: %v", ErrLocked, err)
132		}
133	
134		st, state, err := openStore(abs)
135		if err != nil {
136			syscall.Flock(int(lock.Fd()), syscall.LOCK_UN)
137			lock.Close()
138			return nil, err
139		}
140	
141		q := &Queue{
142			store:    st,
143			flock:    lock,
144			sources:  state.sources,
145			headers:  state.headers,
146			records:  state.records,
147			consumed: state.consumed,
148			now:      state.now,
149			nextSeq:  state.nextSeq,
150		}
151		q.order = q.reconstructOrder()
152		st.snap = q.snapshot
153		return q, nil
154	}
155	
156	// reconstructOrder returns non-terminal record ids in submission (seq) order.
157	func (q *Queue) reconstructOrder() []string {
158		seqs := make([]int64, 0, len(q.records))
159		live := map[int64]string{}
160		for id, rec := range q.records {
161			if isTerminal(rec.Status) {
162				continue
163			}
164			seqs = append(seqs, rec.Seq)
165			live[rec.Seq] = id
166		}
167		sort.Slice(seqs, func(i, j int) bool { return seqs[i] < seqs[j] })
168		order := make([]string, 0, len(seqs))
169		for _, seq := range seqs {
170			order = append(order, live[seq])
171		}
172		return order
173	}
174	
175	// snapshot returns a detached copy of live state for log compaction. Callers
176	// must hold mu.
177	func (q *Queue) snapshot() *loadedState {
178		s := &loadedState{
179			sources:  map[string]bool{},
180			headers:  map[string]Header{},
181			records:  map[string]*Record{},
182			consumed: map[consumeToken]string{},
183			now:      q.now,
184			nextSeq:  q.nextSeq,
185		}
186		for c := range q.sources {
187			s.sources[c] = true
188		}
189		for c, h := range q.headers {
190			s.headers[c] = h
191		}
192		for id, rec := range q.records {
193			cp := *rec
194			s.records[id] = &cp
195		}
196		for k, v := range q.consumed {
197			s.consumed[k] = v
198		}
199		return s
200	}
201	
202	// Close flushes, releases the directory lock and closes the queue.
203	func (q *Queue) Close() error {
204		q.mu.Lock()
205		defer q.mu.Unlock()
206		if q.flock == nil {
207			return nil
208		}
209		var err error
210		if !q.broken {
211			err = q.store.close()
212		} else {
213			q.store.forceClose()
214		}
215		syscall.Flock(int(q.flock.Fd()), syscall.LOCK_UN)
216		q.flock.Close()
217		q.flock = nil
218		return err
219	}
220	
221	// fail locks in a storage failure: the log tail may be partially written, so
222	// no further appends are allowed in this process (another append would turn a
223	// truncatable torn tail into unrecoverable corruption).
224	func (q *Queue) fail(op string, err error) error {
225		q.broken = true
226		return fmt.Errorf("%w: %s: %v", ErrStorage, op, err)
227	}
228	
229	func (q *Queue) checkWritable() error {
230		if q.flock == nil {
231			return fmt.Errorf("%w: queue is closed", ErrStorage)
232		}
233		if q.broken {
234			return fmt.Errorf("%w: a previous write failed; reopen the queue", ErrStorage)
235		}
236		return nil
237	}
238	
239	// RegisterSource records that messages may originate from chain. Idempotent.
240	func (q *Queue) RegisterSource(chain string) error {
241		if chain == "" {
242			return fmt.Errorf("%w: empty source chain", ErrInvalidArg)
243		}
244		q.mu.Lock()
245		defer q.mu.Unlock()
246		if err := q.checkWritable(); err != nil {
247			return err
248		}
249		if q.sources[chain] {
250			return nil
251		}
252		if err := q.store.appendRegisterSource(chain); err != nil {
253			return q.fail("register source", err)
254		}
255		q.sources[chain] = true
256		return q.maybeCompact()
257	}
258	
259	// UpsertHeader stores the latest known header for a chain. A header with
260	// Trusted=false records the chain tip but grants no proof coverage; a later
261	// trusted header covering the proof height can unblock waiting messages.
262	// Header updates never bypass retry scheduling and never reactivate terminal
263	// messages.
264	func (q *Queue) UpsertHeader(h Header) error {
265		if h.Chain == "" {
266			return fmt.Errorf("%w: empty header chain", ErrInvalidArg)
267		}
268		if h.Height < 0 {
269			return fmt.Errorf("%w: negative header height", ErrInvalidArg)
270		}
271		q.mu.Lock()
272		defer q.mu.Unlock()
273		if err := q.checkWritable(); err != nil {
274			return err
275		}
276		if err := q.store.appendHeader(h); err != nil {
277			return q.fail("upsert header", err)
278		}
279		q.headers[h.Chain] = h
280		return q.maybeCompact()
281	}
282	
283	// Submit enqueues a message with an absolute expiry (Unix milliseconds; zero
284	// means never expire). Re-submitting the same id with identical content
285	// returns the existing record without adding a queue entry; the same id with
286	// different content returns ErrConflict and leaves the original untouched;
287	// re-submitting a terminal id returns ErrTerminal. Success is reported only
288	// after the submission is durably persisted.
289	func (q *Queue) Submit(env Envelope) (*Record, error) {
290		m := env.Message
291		if m.ID == "" {
292			return nil, fmt.Errorf("%w: empty message id", ErrInvalidArg)
293		}
294		if m.From == "" || m.To == "" {
295			return nil, fmt.Errorf("%w: empty source or destination chain", ErrInvalidArg)
296		}
297		if m.ProofAt < 0 {
298			return nil, fmt.Errorf("%w: negative proof height", ErrInvalidArg)
299		}
300		if env.ExpiresAt < 0 {
301			return nil, fmt.Errorf("%w: negative expiry time", ErrInvalidArg)
302		}
303	
304		q.mu.Lock()
305		defer q.mu.Unlock()
306		if err := q.checkWritable(); err != nil {
307			return nil, err
308		}
309	
310		if existing, ok := q.records[m.ID]; ok {
311			if isTerminal(existing.Status) {
312				return nil, fmt.Errorf("%w: message %s is %s", ErrTerminal, m.ID, existing.Status)
313			}
314			if sameEnvelope(existing.Msg, env) {
315				out := *existing
316				return &out, nil
317			}
318			return nil, fmt.Errorf("%w: message %s", ErrConflict, m.ID)
319		}
320	
321		rec := &Record{
322			Msg:    env,
323			Status: StatusPending,
324			Reason: "awaiting first processing",
325			Seq:    q.nextSeq,
326		}
327		if err := q.store.appendSubmit(rec); err != nil {
328			return nil, q.fail("submit", err)
329		}
330		q.records[m.ID] = rec
331		q.order = append(q.order, m.ID)
332		q.nextSeq++
333		if err := q.maybeCompact(); err != nil {
334			return nil, err
335		}
336		out := *rec
337		return &out, nil
338	}
339	
340	// Advance moves processing time to nowMs (Unix milliseconds). Equal time may
341	// be advanced repeatedly; going backwards is rejected and changes nothing.
342	//
343	// Each advance, in submission order:
344	//  1. due messages (new messages are due on the next advance; others when now
345	//     has reached their next retry time) are evaluated for replay and expiry,
346	//     replay winning on a tie and now == ExpiresAt counting as expired, then
347	//     for source registration and trusted-header coverage, and finally
348	//     delivered;
349	//  2. afterwards every remaining non-terminal message, regardless of its
350	//     retry schedule, is re-checked for replay and expiry at the new time.
351	//
352	// Unregistered sources are permanently rejected as unknown-source; registered
353	// sources without a trusted header covering the proof height stay waiting and
354	// do not consume the nonce. Waiting retry intervals are 1,2,4,... seconds,
355	// doubling to a 60-second cap, measured from the actual processing time;
356	// jumping over several intervals still costs one attempt.
357	func (q *Queue) Advance(nowMs int64) (*AdvanceReport, error) {
358		if nowMs < 0 {
359			return nil, fmt.Errorf("%w: negative processing time", ErrInvalidArg)
360		}
361		q.mu.Lock()
362		defer q.mu.Unlock()
363		if err := q.checkWritable(); err != nil {
364			return nil, err
365		}
366		if q.now != 0 && nowMs < q.now {
367			return nil, fmt.Errorf("%w: processing time %d precedes last advanced time %d", ErrInvalidArg, nowMs, q.now)
368		}
369	
370		report := &AdvanceReport{Now: nowMs}
371	
372		// Phase 1: due messages, first-submission order.
373		for _, id := range append([]string(nil), q.order...) {
374			rec := q.records[id]
375			if rec == nil || isTerminal(rec.Status) {
376				continue
377			}
378			due := rec.Attempts == 0 || nowMs >= rec.NextRetry
379			if !due {
380				continue
381			}
382			if r, done, err := q.checkReplayExpiry(rec, nowMs); err != nil {
383				return nil, err
384			} else if done {
385				report.Results = append(report.Results, r)
386				continue
387			}
388			r, err := q.processDue(rec, nowMs)
389			if err != nil {
390				return nil, err
391			}
392			report.Results = append(report.Results, r)
393		}
394	
395		// Phase 2: replay/expiry hold for every non-terminal message at the new
396		// time, even while its retry backoff is still running.
397		for _, id := range append([]string(nil), q.order...) {
398			rec := q.records[id]
399			if rec == nil || isTerminal(rec.Status) {
400				continue
401			}
402			if r, done, err := q.checkReplayExpiry(rec, nowMs); err != nil {
403				return nil, err
404			} else if done {
405				report.Results = append(report.Results, r)
406			}
407		}
408	
409		if err := q.store.appendAdvance(nowMs); err != nil {
410			return nil, q.fail("advance", err)
411		}
412		q.now = nowMs
413		if err := q.maybeCompact(); err != nil {
414			return nil, err
415		}
416		return report, nil
417	}
418	
419	// maybeCompact rewrites the WAL as a snapshot once it grows past the
420	// threshold. Live state already reflects every acknowledged append, so the
421	// snapshot cannot lose records. A compaction failure is a storage failure:
422	// the queue is marked broken and must be reopened.
423	func (q *Queue) maybeCompact() error {
424		if !q.store.needsCompaction() {
425			return nil
426		}
427		if err := q.store.compact(q.snapshot()); err != nil {
428			return q.fail("compact log", err)
429		}
430		return nil
431	}
432	
433	// checkReplayExpiry terminalizes rec when its nonce was consumed by another
434	// message or its absolute expiry has been reached. Replay wins when both
435	// hold. The bool reports whether the message was terminalized.
436	func (q *Queue) checkReplayExpiry(rec *Record, now int64) (Result, bool, error) {
437		id := rec.Msg.Message.ID
438		token := newConsumeToken(rec.Msg.Message.From, rec.Msg.Message.To, rec.Msg.Message.Nonce)
439		if winner, taken := q.consumed[token]; taken && winner != id {
440			reason := "nonce combination already consumed by message " + winner
441			if err := q.terminalize(rec, now, StatusReplay, reason); err != nil {
442				return Result{}, false, err
443			}
444			return Result{ID: id, Status: StatusReplay, Reason: reason}, true, nil
445		}
446		if rec.Msg.ExpiresAt != 0 && now >= rec.Msg.ExpiresAt {
447			reason := "expired at " + strconv.FormatInt(rec.Msg.ExpiresAt, 10)
448			if err := q.terminalize(rec, now, StatusExpired, reason); err != nil {
449				return Result{}, false, err
450			}
451			return Result{ID: id, Status: StatusExpired, Reason: reason}, true, nil
452		}
453		return Result{}, false, nil
454	}
455	
456	// processDue classifies a due message against source registration and header
457	// trust, or delivers it.
458	func (q *Queue) processDue(rec *Record, now int64) (Result, error) {
459		id := rec.Msg.Message.ID
460		if !q.sources[rec.Msg.Message.From] {
461			reason := "unknown source chain " + rec.Msg.Message.From
462			if err := q.terminalize(rec, now, StatusUnknownSrc, reason); err != nil {
463				return Result{}, err
464			}
465			return Result{ID: id, Status: StatusUnknownSrc, Reason: reason}, nil
466		}
467		h, hasHeader := q.headers[rec.Msg.Message.From]
468		if !hasHeader || !h.Trusted || h.Height < rec.Msg.Message.ProofAt {
469			cur := int64(0)
470			if hasHeader {
471				cur = h.Height
472			}
473			reason := fmt.Sprintf("waiting for trusted header covering height %d (current %d)", rec.Msg.Message.ProofAt, cur)
474			if err := q.markWaiting(rec, now, reason); err != nil {
475				return Result{}, err
476			}
477			return Result{ID: id, Status: StatusWaiting, Reason: reason}, nil
478		}
479	
480		// Deliver: success record and nonce consumption are one log entry.
481		token := newConsumeToken(rec.Msg.Message.From, rec.Msg.Message.To, rec.Msg.Message.Nonce)
482		reason := "delivered; proof verified by trusted header at height " + strconv.FormatInt(h.Height, 10)
483		if err := q.store.appendResult(now, rec, StatusSuccess, reason, rec.Attempts+1, &token, id); err != nil {
484			return Result{}, q.fail("deliver", err)
485		}
486		rec.Attempts++
487		rec.LastProcAt = now
488		rec.Status = StatusSuccess
489		rec.Reason = reason
490		rec.NextRetry = 0
491		q.consumed[token] = id
492		q.removeFromOrder(id)
493		return Result{ID: id, Status: StatusSuccess, Reason: reason}, nil
494	}
495	
496	func (q *Queue) terminalize(rec *Record, now int64, status, reason string) error {
497		if err := q.store.appendResult(now, rec, status, reason, rec.Attempts+1, nil, ""); err != nil {
498			return q.fail("terminalize", err)
499		}
500		rec.Attempts++
501		rec.LastProcAt = now
502		rec.Status = status
503		rec.Reason = reason
504		rec.NextRetry = 0
505		q.removeFromOrder(rec.Msg.Message.ID)
506		return nil
507	}
508	
509	func (q *Queue) markWaiting(rec *Record, now int64, reason string) error {
510		attempt := rec.Attempts + 1
511		if err := q.store.appendResult(now, rec, StatusWaiting, reason, attempt, nil, ""); err != nil {
512			return q.fail("schedule retry", err)
513		}
514		rec.Attempts = attempt
515		rec.LastProcAt = now
516		rec.Status = StatusWaiting
517		rec.Reason = reason
518		rec.NextRetry = now + nextRetryDelay(attempt)
519		return nil
520	}
521	
522	func (q *Queue) removeFromOrder(id string) {
523		for i, cand := range q.order {
524			if cand == id {
525				q.order = append(q.order[:i], q.order[i+1:]...)
526				return
527			}
528		}
529	}
530	
531	// nextRetryDelay is the backoff after the attempt-th processing (1-based):
532	// 1s, 2s, 4s, 8s, 16s, 32s, then 60s capped, in milliseconds.
533	func nextRetryDelay(attempt int) int64 {
534		if attempt < 1 {
535			attempt = 1
536		}
537		if attempt > 6 {
538			return 60_000
539		}
540		return int64(1) << (attempt - 1) * 1000
541	}
542	
543	func isTerminal(status string) bool {
544		switch status {
545		case StatusSuccess, StatusReplay, StatusExpired, StatusUnknownSrc:
546			return true
547		}
548		return false
549	}
550	
551	func sameEnvelope(a, b Envelope) bool {
552		return a.ExpiresAt == b.ExpiresAt &&
553			a.Message.ID == b.Message.ID &&
554			a.Message.From == b.Message.From &&
555			a.Message.To == b.Message.To &&
556			a.Message.Nonce == b.Message.Nonce &&
557			a.Message.Payload == b.Message.Payload &&
558			a.Message.ProofAt == b.Message.ProofAt
559	}
560	
561	// Query returns the current state of a message.
562	func (q *Queue) Query(id string) (Query, bool) {
563		q.mu.Lock()
564		defer q.mu.Unlock()
565		rec, ok := q.records[id]
566		if !ok {
567			return Query{}, false
568		}
569		return toQuery(rec), true
570	}
571	
572	// Queries returns all records in first-submission order.
573	func (q *Queue) Queries() []Query {
574		q.mu.Lock()
575		defer q.mu.Unlock()
576		out := make([]Query, 0, len(q.records))
577		for _, rec := range q.records {
578			out = append(out, toQuery(rec))
579		}
580		sort.Slice(out, func(i, j int) bool {
581			return q.records[out[i].ID].Seq < q.records[out[j].ID].Seq
582		})
583		return out
584	}
585	
586	// Now returns the last advanced processing time, or 0 if never advanced.
587	func (q *Queue) Now() int64 {
588		q.mu.Lock()
589		defer q.mu.Unlock()
590		return q.now
591	}
592	
593	func toQuery(rec *Record) Query {
594		return Query{
595			ID:        rec.Msg.Message.ID,
596			From:      rec.Msg.Message.From,
597			To:        rec.Msg.Message.To,
598			Nonce:     rec.Msg.Message.Nonce,
599			Payload:   rec.Msg.Message.Payload,
600			ProofAt:   rec.Msg.Message.ProofAt,
601			ExpiresAt: rec.Msg.ExpiresAt,
602			Status:    rec.Status,
603			Reason:    rec.Reason,
604			NextRetry: rec.NextRetry,
605			Attempts:  rec.Attempts,
606		}
607	}
608

