504	func (s *store) close() error {
505		if s.f == nil {
506			return nil
507		}
508		err := s.f.Sync()
509		cerr := s.f.Close()
510		s.f = nil
511		if err != nil {
512			return err
513		}
514		return cerr
515	}
516	
517	// forceClose releases the file without the final sync after a failed write.
518	func (s *store) forceClose() {
519		if s.f == nil {
520			return
521		}
522		s.f.Close()
523		s.f = nil
524	}
525	
526	// append writes one framed, checksummed, fsynced record.
527	func (s *store) append(e *logEntry) error {
528		if s.injectErr != nil {
529			return s.injectErr
530		}
531		body, err := json.Marshal(e)
532		if err != nil {
533			return fmt.Errorf("encode log entry: %w", err)
534		}
535		if _, err := s.f.Write(encodeFrame(body)); err != nil {
536			return fmt.Errorf("write %s: %w", logName, err)
537		}
538		if err := s.f.Sync(); err != nil {
539			return fmt.Errorf("sync %s: %w", logName, err)
540		}
541		if info, err := s.f.Stat(); err == nil {
542			s.size = info.Size()
543		} else {
544			s.size += int64(frameHeaderSize + len(body) + frameCRCsSize)
545		}
546		return nil
547	}
548	
549	// needsCompaction reports whether the log crossed the compaction threshold.
550	func (s *store) needsCompaction() bool {
551		return s.size > compactThreshold && s.snap != nil
552	}
