564		return s.append(&logEntry{
565			T: kindSubmit, Seq: rec.Seq, ID: m.ID, From: m.From, To: m.To,
566			Nonce: m.Nonce, Payload: m.Payload, ProofAt: m.ProofAt, ExpiresAt: rec.Msg.ExpiresAt,
