570	// appendResult records one processing outcome. On success the consumed triple
571	// (consumeFrom/consumeTo/consumeNonce) and its consumer are part of the same
572	// durable record, committing together atomically. token is nil for every
573	// non-success status.
574	func (s *store) appendResult(now int64, rec *Record, status, reason string, attempts int, token *consumeToken, consumeBy string) error {
575		e := &logEntry{
576			T: kindResult, Now: now, ID: rec.Msg.Message.ID,
577			Status: status, Reason: reason, Attempts: attempts,
578		}
579		if status == StatusWaiting {
580			e.NextRetry = now + nextRetryDelay(attempts)
581		}
582		if status == StatusSuccess {
583			if token == nil || consumeBy == "" {
584				return fmt.Errorf("internal error: success result for %q missing nonce consumption", rec.Msg.Message.ID)
585			}
586			e.ConsumeFrom = token.from
587			e.ConsumeTo = token.to
588			e.ConsumeNonce = token.nonce
589			e.ConsumeBy = consumeBy
590		}
591		return s.append(e)
592	}
