598	// compact atomically replaces the log with a deterministic snapshot of live
599	// state. It must run while Queue.mu is held (no concurrent mutation), and only
600	// after in-memory state reflects every acknowledged append.
601	func (s *store) compact(state *loadedState) error {
602		entries := []*logEntry{{T: kindVersion, V: currentLogV}}
603	
604		chains := make([]string, 0, len(state.sources))
605		for c := range state.sources {
606			chains = append(chains, c)
607		}
608		sort.Strings(chains)
609		for _, c := range chains {
610			entries = append(entries, &logEntry{T: kindSource, Chain: c})
611		}
612	
613		headerChains := make([]string, 0, len(state.headers))
614		for c := range state.headers {
615			headerChains = append(headerChains, c)
616		}
617		sort.Strings(headerChains)
618		for _, c := range headerChains {
619			h := state.headers[c]
620			entries = append(entries, &logEntry{T: kindHeader, Chain: h.Chain, Height: h.Height, Root: h.Root, Trusted: h.Trusted})
621		}
622	
623		seqs := make([]int64, 0, len(state.records))
624		bySeq := make(map[int64]*Record, len(state.records))
625		for _, rec := range state.records {
626			seqs = append(seqs, rec.Seq)
627			bySeq[rec.Seq] = rec
628		}
629		sort.Slice(seqs, func(i, j int) bool { return seqs[i] < seqs[j] })
630		for _, seq := range seqs {
631			rec := bySeq[seq]
632			m := rec.Msg.Message
633			entries = append(entries, &logEntry{
634				T: kindSubmit, Seq: rec.Seq, ID: m.ID, From: m.From, To: m.To,
635				Nonce: m.Nonce, Payload: m.Payload, ProofAt: m.ProofAt, ExpiresAt: rec.Msg.ExpiresAt,
636			})
637			if rec.Attempts > 0 {
638				re := &logEntry{
639					T: kindState, Now: rec.LastProcAt, ID: m.ID,
640					Status: rec.Status, Reason: rec.Reason, Attempts: rec.Attempts,
641				}
642				if rec.Status == StatusWaiting {
643					re.NextRetry = rec.NextRetry
644				}
645				if rec.Status == StatusSuccess {
646					re.ConsumeFrom = m.From
647					re.ConsumeTo = m.To
648					re.ConsumeNonce = m.Nonce
649					re.ConsumeBy = m.ID
650				}
651				entries = append(entries, re)
652			}
653		}
654		if state.now > 0 {
655			entries = append(entries, &logEntry{T: kindAdvance, Now: state.now})
656		}
657	
658		tmp := filepath.Join(s.dir, logName+".compact")
659		f, err := os.OpenFile(tmp, os.O_RDWR|os.O_CREATE|os.O_TRUNC, compactFileMode)
660		if err != nil {
661			return err
662		}
663		abort := func(err error) error {
664			f.Close()
665			os.Remove(tmp)
666			return err
667		}
668		if _, err := f.WriteString(logMagic); err != nil {
669			return abort(err)
670		}
671		for _, e := range entries {
672			body, err := json.Marshal(e)
673			if err != nil {
674				return abort(err)
675			}
676			if _, err := f.Write(encodeFrame(body)); err != nil {
677				return abort(err)
678			}
679		}
680		if err := f.Sync(); err != nil {
681			return abort(err)
682		}
683		if err := f.Close(); err != nil {
684			os.Remove(tmp)
685			return err
686		}
687		if err := os.Rename(tmp, filepath.Join(s.dir, logName)); err != nil {
688			os.Remove(tmp)
689			return err
690		}
691		if err := syncDir(s.dir); err != nil {
692			return err
693		}
694		nf, err := os.OpenFile(filepath.Join(s.dir, logName), os.O_RDWR|os.O_APPEND, compactFileMode)
695		if err != nil {
696			return err
697		}
698		if _, err := nf.Seek(0, io.SeekEnd); err != nil {
699			nf.Close()
700			return err
701		}
702		s.f.Close()
703		s.f = nf
704		if info, err := nf.Stat(); err == nil {
705			s.size = info.Size()
706		}
707		return nil
708	}
709	
710	// syncDir fsyncs a directory so that file creation and rename survive a crash.
711	func syncDir(dir string) error {
712		d, err := os.Open(dir)
713		if err != nil {
714			return fmt.Errorf("open directory for sync: %w", err)
715		}
716		defer d.Close()
717		if err := d.Sync(); err != nil {
718			return fmt.Errorf("sync directory %s: %w", dir, err)
719		}
720		return nil
721	}
722

