107	type globalFlags struct {
108		state string
109	}
110	
111	func newQueueFlagSet(name string, g *globalFlags) *flag.FlagSet {
112		fs := flag.NewFlagSet(name, flag.ContinueOnError)
113		fs.SetOutput(os.Stderr)
114		fs.StringVar(&g.state, "state", "", "state directory (required)")
115		return fs
116	}
