118	func (g *globalFlags) mustState() {
119		if g.state == "" {
120			fmt.Fprintln(os.Stderr, "error: --state is required")
121			os.Exit(2)
122		}
123	}
124	
125	func queueCmdRegisterSource(rest []string) error {
126		g := &globalFlags{}
127		fs := newQueueFlagSet("register-source", g)
128		chain := fs.String("chain", "", "source chain name (required)")
129		if err := fs.Parse(rest); err != nil {
130			return err
131		}
132		if *chain == "" {
133			return fmt.Errorf("%w: --chain is required", relayproof.ErrInvalidArg)
134		}
135		g.mustState()
136		q, err := relayproof.Open(g.state)
137		if err != nil {
138			return err
139		}
140		defer q.Close()
141		if err := q.RegisterSource(*chain); err != nil {
142			return err
143		}
144		fmt.Printf("registered source chain %s\n", *chain)
145		return nil
146	}
147	
148	func queueCmdHeader(rest []string) error {
149		g := &globalFlags{}
150		fs := newQueueFlagSet("header", g)
151		chain := fs.String("chain", "", "chain name (required)")
152		height := fs.Int64("height", -1, "header height (required)")
153		root := fs.String("root", "", "header commitment root")
154		trusted := fs.Bool("trusted", false, "mark the header as trusted")
155		if err := fs.Parse(rest); err != nil {
156			return err
157		}
158		if *chain == "" || *height < 0 {
159			return fmt.Errorf("%w: --chain and non-negative --height are required", relayproof.ErrInvalidArg)
160		}
161		g.mustState()
162		q, err := relayproof.Open(g.state)
163		if err != nil {
164			return err
165		}
166		defer q.Close()
167		h := relayproof.Header{Chain: *chain, Height: *height, Root: *root, Trusted: *trusted}
168		if err := q.UpsertHeader(h); err != nil {
169			return err
170		}
171		fmt.Printf("stored header chain=%s height=%d trusted=%t\n", *chain, *height, *trusted)
172		return nil
173	}
174	
175	func queueCmdSubmit(rest []string) error {
176		g := &globalFlags{}
177		fs := newQueueFlagSet("submit", g)
178		id := fs.String("id", "", "message id (required)")
179		from := fs.String("from", "", "source chain (required)")
180		to := fs.String("to", "", "destination chain (required)")
181		nonce := fs.Uint64("nonce", 0, "message nonce on the source chain")
182		payload := fs.String("payload", "", "message payload")
183		proofAt := fs.Int64("proof-at", -1, "height at which the message is proven (required)")
184		expiresAt := fs.Int64("expires-at", 0, "absolute expiry as Unix ms; 0 means never")
185		if err := fs.Parse(rest); err != nil {
186			return err
187		}
188		if *id == "" || *from == "" || *to == "" || *proofAt < 0 {
189			return fmt.Errorf("%w: --id, --from, --to and non-negative --proof-at are required", relayproof.ErrInvalidArg)
190		}
191		g.mustState()
192		q, err := relayproof.Open(g.state)
193		if err != nil {
194			return err
195		}
196		defer q.Close()
197		rec, err := q.Submit(relayproof.Envelope{
198			Message: relayproof.Message{
199				ID: *id, From: *from, To: *to, Nonce: *nonce,
200				Payload: *payload, ProofAt: *proofAt,
201			},
202			ExpiresAt: *expiresAt,
203		})
204		if err != nil {
205			return err
206		}
207		return emitJSON(recordJSON(rec))
208	}
209	
210	func queueCmdAdvance(rest []string) error {
211		g := &globalFlags{}
212		fs := newQueueFlagSet("advance", g)
213		now := fs.Int64("now", -1, "processing time as Unix milliseconds (required)")
214		if err := fs.Parse(rest); err != nil {
215			return err
216		}
217		if *now < 0 {
218			return fmt.Errorf("%w: non-negative --now is required", relayproof.ErrInvalidArg)
219		}
220		g.mustState()
221		q, err := relayproof.Open(g.state)
222		if err != nil {
223			return err
224		}
225		defer q.Close()
226		report, err := q.Advance(*now)
227		if err != nil {
228			return err
229		}
230		return emitJSON(advanceJSON(report))
231	}
232	
233	func queueCmdQuery(rest []string) error {
234		g := &globalFlags{}
235		fs := newQueueFlagSet("query", g)
236		id := fs.String("id", "", "message id; omit to list all records in submission order")
237		if err := fs.Parse(rest); err != nil {
238			return err
239		}
240		g.mustState()
241		q, err := relayproof.Open(g.state)
242		if err != nil {
243			return err
244		}
245		defer q.Close()
246		if *id != "" {
247			rec, ok := q.Query(*id)
248			if !ok {
249				return fmt.Errorf("no record for message %q", *id)
250			}
251			return emitJSON(queryJSON(rec))
252		}
253		for _, rec := range q.Queries() {
254			if err := emitJSON(queryJSON(rec)); err != nil {
255				return err
256			}
257		}
258		return nil
259	}
260	
261	type jsonRecord struct {
262		ID        string `json:"id"`
263		Status    string `json:"status"`
264		Reason    string `json:"reason"`
265		Attempts  int    `json:"attempts"`
266		NextRetry int64  `json:"nextRetryMs,omitempty"`
267		ExpiresAt int64  `json:"expiresAtMs,omitempty"`
268	}
269	
270	func recordJSON(r *relayproof.Record) jsonRecord {
271		return jsonRecord{
272			ID: r.Msg.Message.ID, Status: r.Status, Reason: r.Reason,
273			Attempts: r.Attempts, NextRetry: r.NextRetry, ExpiresAt: r.Msg.ExpiresAt,
274		}
275	}
276	
277	type jsonQuery struct {
278		ID        string `json:"id"`
279		From      string `json:"from"`
280		To        string `json:"to"`
281		Nonce     uint64 `json:"nonce"`
282		Payload   string `json:"payload"`
283		ProofAt   int64  `json:"proofAtHeight"`
284		ExpiresAt int64  `json:"expiresAtMs,omitempty"`
285		Status    string `json:"status"`
286		Reason    string `json:"reason"`
287		Attempts  int    `json:"attempts"`
288		NextRetry int64  `json:"nextRetryMs,omitempty"`
289	}
290	
291	func queryJSON(q relayproof.Query) jsonQuery {
292		return jsonQuery{
293			ID: q.ID, From: q.From, To: q.To, Nonce: q.Nonce, Payload: q.Payload,
294			ProofAt: q.ProofAt, ExpiresAt: q.ExpiresAt, Status: q.Status,
295			Reason: q.Reason, Attempts: q.Attempts, NextRetry: q.NextRetry,
296		}
297	}
298	
299	type jsonAdvance struct {
300		NowMs   int64               `json:"nowMs"`
301		Results []relayproof.Result `json:"results"`
302	}
303	
304	func advanceJSON(r *relayproof.AdvanceReport) jsonAdvance {
305		return jsonAdvance{NowMs: r.Now, Results: r.Results}
306	}
307	
308	func emitJSON(v any) error {
309		enc := json.NewEncoder(os.Stdout)
310		enc.SetEscapeHTML(false)
311		if err := enc.Encode(v); err != nil {
312			return fmt.Errorf("encode output: %w", err)
313		}
314		return nil
315	}
316	
317	func runDemo() {
318		headers := map[string]relayproof.Header{
319			"chain-a": {Chain: "chain-a", Height: 1024, Root: "0xabc", Trusted: true},
320		}
321		consumed := map[string]bool{}
322		messages := []relayproof.Message{
323			{ID: "msg-1", From: "chain-a", To: "chain-b", Nonce: 7, ProofAt: 1000},
324			{ID: "msg-2", From: "chain-c", To: "chain-b", Nonce: 1, ProofAt: 10},
325		}
326		for _, message := range messages {
327			delivery := relayproof.Verify(headers, message, consumed)
328			fmt.Printf("message=%s status=%s reason=%s\n", delivery.Message, delivery.Status, delivery.Reason)
329		}
330		replay := relayproof.Verify(headers, messages[0], consumed)
331		fmt.Printf("replay of %s status=%s reason=%s\n", replay.Message, replay.Status, replay.Reason)
332		fmt.Println("pending:", relayproof.Pending(headers, messages))
333	}
