291	// A not-yet-expired message with a covering trusted header can still succeed
292	// at its retry instant; one millisecond later it would expire.
293	func TestSuccessJustBeforeExpiry(t *testing.T) {
294		q, _ := openTempQueue(t)
295		defer q.Close()
296		q.RegisterSource("a")
297		q.UpsertHeader(Header{Chain: "a", Height: 100, Trusted: true})
298		q.Submit(env("m", "a", "b", 1, 10, 2001))
299		q.Advance(1000) // success
