535	// Corrupt and unsupported formats must be rejected, never silently cleared.
536	func TestCorruptionRejected(t *testing.T) {
537		cases := map[string][]byte{
538			"foreign magic":   []byte("NOT-A-RELAYPROOF-LOG!!\n"),
539			"truncated magic": []byte("RELAY"),
540			"empty":           nil,
541			"bad version":     append([]byte(logMagic), encodeFrame(mustMarshal(&logEntry{T: "version", V: 9}))...),
542		}
543		for name, data := range cases {
544			t.Run(name, func(t *testing.T) {
545				dir := t.TempDir()
546				path := filepath.Join(dir, logName)
547				if err := os.WriteFile(path, data, 0o600); err != nil {
548					t.Fatal(err)
549				}
