552					if q != nil {
553						q.Close()
554					}
555					t.Fatalf("want ErrCorrupt, got %v", err)
556				}
557				// Original bytes must still be there (not wiped).
558				got, err := os.ReadFile(path)
559				if err != nil {
560					t.Fatal(err)
561				}
562				if name == "empty" {
563					if len(got) != 0 {
564						t.Fatalf("empty file must not be rewritten on failed open")
565					}
566				} else if len(got) != len(data) {
567					t.Fatalf("corrupt state was modified: %d -> %d bytes", len(data), len(got))
568				}
569			})
570		}
571	}
